import programsJson from "./budget-programs.json";
import type { BudgetProgram, BudgetProgramsData } from "@/lib/types";

// Per-program detail, generated by scripts/extract_budget.py alongside budget.json — never
// edit by hand. ~2MB: import only from server components (the program pages are static).
const DATA = programsJson as BudgetProgramsData;

export function getProgram(year: number, slug: string): BudgetProgram | undefined {
  return DATA.years[String(year)]?.find(p => p.slug === slug);
}

/** Years whose file has a program with this exact slug (program names change over time). */
export function programYears(slug: string): number[] {
  return Object.keys(DATA.years).map(Number).filter(y => DATA.years[String(y)].some(p => p.slug === slug)).sort((a, b) => a - b);
}

export function allProgramParams(): { year: string; program: string }[] {
  return Object.entries(DATA.years).flatMap(([year, progs]) => progs.map(p => ({ year, program: p.slug })));
}
